// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to a reasonable range to avoid issues
        amount = bound(amount, 1, 1000000);
        // Ensure we are not the owner for the test (owner is address(this))
        vm.assume(msg.sender != address(this));
        // Call AdjustBetAmounts as a non-owner (will revert in reference, succeed in mutant)
        // We need to handle revert to still check the property
        bool reverted;
        try c.AdjustBetAmounts(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // The property: After any call to AdjustBetAmounts (whether it reverts or not),
        // the contract must still be closed to the public.
        // Since onlyOwner modifier prevents state changes in reference, openToPublic stays false.
        // In mutant, non-owner can call and modify betLimit but openToPublic is unchanged.
        assertTrue(!c.OpenToThePublic());
    }
}

