pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to avoid overflow issues
        amount = bound(amount, 0, type(uint256).max / 2);

        // Record the betLimit before the call
        uint256 oldBetLimit = c.currentBetLimit();
        uint256 oldDifficulty = c.currentDifficulty();

        // Call AdjustBetAmounts
        vm.expectEmit(true, true, true, true);
        // The correct event should emit BetLimitChanged with the new amount
        emit BetLimitChanged(c.currentBetLimit());

        // But we don't actually check events in the property; instead we use a state-based assertion
        // Since AdjustBetAmounts public — we just call it
        c.AdjustBetAmounts(amount);

        // The general rule: AdjustBetAmounts changes betLimit but does NOT change difficulty
        // So after the call: c.currentBetLimit() == amount, and c.currentDifficulty() == oldDifficulty
        assertTrue(c.currentBetLimit() == amount && c.currentDifficulty() == oldDifficulty && amount == c.currentBetLimit());
    }

    // Helper event to match signature for expectEmit (optional, not used in assertion)
    event BetLimitChanged(uint256);
}

