pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 newBetLimit) public {
        vm.assume(newBetLimit > 0 && newBetLimit <= 1e18);
        c.AdjustBetAmounts(newBetLimit);
        // Try to wager with exactly newBetLimit; reference succeeds, mutant reverts
        bool refSucceeds = false;
        bool mutSucceeds = false;
        vm.prank(address(0x1));
        vm.deal(address(0x1), newBetLimit * 4);
        (bool success, ) = address(c).call{value: newBetLimit}(abi.encodeWithSignature("wager()"));
        refSucceeds = success;
        // For mutant, try wager with newBetLimit + 1 (the mutant's requirement)
        vm.prank(address(0x2));
        vm.deal(address(0x2), newBetLimit * 4);
        (bool success2, ) = address(c).call{value: newBetLimit + 1}(abi.encodeWithSignature("wager()"));
        mutSucceeds = success2;
        // The rule: in the reference, wager succeeds with exactly newBetLimit and fails with newBetLimit+1
        // In the mutant, wager fails with newBetLimit and succeeds with newBetLimit+1
        assertTrue(refSucceeds && !mutSucceeds);
    }
}

